180: /**
181:  * 완주 표시는 **전 UI 단일 정책**(`isRouteCompletion` = 98%)을 쓴다(§2.6).
182:  * 반올림 백분율 95% 로 판정하던 표시는 95~97% Ride 를 「완주」로 보여 주면서
183:  * SavedRoute 는 미완주로 남는 불일치를 만들었다.
184:  */
185: function rideCompletionDisplay(s: StoredRideSession): {
186:   label: string;
187:   isCompleted: boolean;
188:   title: string;
189: } {
190:   const r = s.completionRatio;
191:   if (typeof r !== "number" || !Number.isFinite(r)) {
192:     return { label: "—", isCompleted: false, title: "완주율 없음" };
193:   }
194:   const clamped = Math.max(0, Math.min(1, r));
195:   const pct = Math.round(clamped * 100);
196:   const isCompleted = isRouteCompletion(clamped);
197:   const label = isCompleted ? "완주" : `미완주 (${pct}%)`;
198:   const completionPct = Math.round(ROUTE_COMPLETION_RATIO_THRESHOLD * 100);
199:   const title = isCompleted
200:     ? `계획 경로 대비 ${completionPct}% 이상 주행(완주로 표시)`
201:     : `계획 경로 대비 ${pct}%`;
202:   return { label, isCompleted, title };
203: }
