90: function formatElapsedFromSec(sec: number): string {
91:   const totalMin = Math.floor(sec / 60);
92:   const h = Math.floor(totalMin / 60);
93:   const m = totalMin % 60;
94:   if (h > 0) return `${h}h ${m}m`;
95:   return `${m}m`;
96: }
97: 
98: /** 마일리지 블록 전용 — 한국어 "H시간 M분" 포맷(formatElapsedFromSec 은 영문 "Xh Ym" 이라 별도 함수) */
99: function formatMileageElapsedKo(sec: number): string {
100:   const h = Math.floor(sec / 3600);
101:   const m = Math.floor((sec % 3600) / 60);
102:   return `${h}시간 ${m}분`;
103: }
104: 
105: /**
106:  * 출발·도착 한 줄(전체 주소는 title 로 노출, 한 줄은 CSS 말줄임).
107:  * **실제 세션 지명**을 우선하고, 없으면 계획 Route 지명으로 폴백한다(legacy Ride 호환, §4.1).
108:  */
109: function rideSessionPlacesCaption(s: StoredRideSession): string {
110:   const a = s.sessionStartPlaceLabel?.trim() || s.startPlaceLabel?.trim();
111:   const b = s.sessionEndPlaceLabel?.trim() || s.endPlaceLabel?.trim();
112:   if (a && b) return `${a} / ${b}`;
113:   if (a) return a;
114:   if (b) return b;
115:   return "주소 없음";
116: }
117: 
118: function formatRideEndedAtKo(iso: string): string {
119:   const d = new Date(iso);
120:   if (Number.isNaN(d.getTime())) return "—";
121:   return d.toLocaleString("ko-KR", {
122:     year: "numeric",
123:     month: "numeric",
124:     day: "numeric",
125:     hour: "numeric",
126:     minute: "2-digit",
127:   });
128: }
129: 
130: function formatSessionAvgSpeedKmh(s: StoredRideSession): string {
131:   const v = Number(s.avgSpeedKmh);
132:   if (Number.isFinite(v) && v >= 0) return v.toFixed(1);
133:   if (s.elapsedSec > 0) {
134:     return ((s.distanceMeters / 1000) / (s.elapsedSec / 3600)).toFixed(1);
135:   }
136:   return "0.0";
137: }
138: 
139: function formatSessionCaloriesEstimate(s: StoredRideSession): string {
140:   if (s.caloriesEstimate == null) return "—";
141:   const v = Number(s.caloriesEstimate);
142:   if (!Number.isFinite(v) || v < 0) return "—";
143:   const n = Math.round(v);
144:   return isLegacyDistanceCalories(s) ? `${n} kcal(옛)` : `${n} kcal`;
145: }
146: 
147: /** 전부 미산정이면 합계 0을 「운동 소모 0」으로 읽지 않게 — 표시 */
148: function formatPeriodCaloriesTotal(stats: {
149:   rides: number;
150:   caloriesEstimate: number;
151:   caloriesUnknownCount: number;
152: }): string {
153:   if (stats.rides > 0 && stats.caloriesUnknownCount >= stats.rides) return "—";
154:   return String(Math.round(stats.caloriesEstimate));
155: }
156: 
157: function formatLastRideWhenKo(iso: string, now: Date = new Date()): string {
158:   const d = new Date(iso);
159:   if (Number.isNaN(d.getTime())) return "—";
160:   const diffMs = now.getTime() - d.getTime();
161:   if (diffMs < 0) return formatRideEndedAtKo(iso);
162:   const diffMin = Math.floor(diffMs / 60_000);
163:   if (diffMin < 1) return "방금";
164:   if (diffMin < 60) return `${diffMin}분 전`;
165:   const diffHr = Math.floor(diffMin / 60);
166:   if (diffHr < 24) return `${diffHr}시간 전`;
167:   const diffDay = Math.floor(diffHr / 24);
168:   if (diffDay < 7) return `${diffDay}일 전`;
169:   return formatRideEndedAtKo(iso);
170: }
